// Shared types for the CEFR chat diagnosis.
//
// There is no question list here: expert-authored questions come from the server
// (with the answer key kept server-side), and auto slots are generated by the
// model. The client only carries the transcript and the final verdict. An option
// question arrives with its shuffled option values; the learner clicks one (or
// several) or types a free answer, and the picks ride back in `selected`.

/** Fallback answer-length cap. The live value comes from the admin-configurable
 *  /language-diagnosis/config endpoint; this constant only applies until that
 *  call lands or if it fails. The backend still hard-caps at MAX_MESSAGE_CHARS. */
export const DIAGNOSIS_ANSWER_MAX_CHARS = 2000;

/** Fallback question count. The live value comes from the admin-configurable
 *  /language-diagnosis/config endpoint (len of the question plan); this constant
 *  only applies until that call lands or if it fails. Used for the "question X of
 *  N" counter. Matches the shipped default plan (A1..C2, two per band). */
export const DIAGNOSIS_QUESTION_COUNT = 12;

// The six CEFR outcomes. Every one is a plain CEFR glyph shown as itself. See
// VALID_LEVELS in aia_diagnosis_chat.py.
export type CEFRLevel = "A1" | "A2" | "B1" | "B2" | "C1" | "C2";
export type Skill = "grammar" | "vocabulary" | "reading" | "writing" | "pragmatics";

export interface ChatTurn {
  role: "assistant" | "user";
  content: string;
  /** Assistant option question: the shown option values, already shuffled by the
   *  server. The correct flags never reach the client. */
  options?: string[];
  /** Assistant option question: several options may be correct, so the learner
   *  picks with checkboxes instead of a single radio choice. */
  multi?: boolean;
  /** User turn: the option values the learner clicked. Absent when they typed a
   *  free answer, which the final grading call interprets. */
  selected?: string[];
}

/** The wire shape of one transcript entry posted back each turn. The options and
 *  the picks travel so the server can reconstruct the record for the one final
 *  grading call; `multi` is display-only and stays on the client. */
export function toTranscript(turns: ChatTurn[]): {
  role: ChatTurn["role"];
  content: string;
  options?: string[];
  selected?: string[];
}[] {
  return turns.map(({ role, content, options, selected }) => ({
    role,
    content,
    ...(options ? { options } : {}),
    ...(selected ? { selected } : {}),
  }));
}

export interface DiagnosisResult {
  level: CEFRLevel;
  /** Closing feedback, written in the workspace's diagnosis language. */
  message: string;
  skill_scores: Record<Skill, number>;
}

/** One turn of the diagnosis: the next question, or the final verdict. */
export type DiagnosisTurnResponse =
  | { done: false; message: string; options?: string[]; multi?: boolean }
  | ({ done: true } & DiagnosisResult);
